import { js } from "cc";
import { NetAdaptor } from "../../framework/network/NetAdaptor";
import { Global } from "../../main/Global";
import NetMgr from "../../mgr/NetMgr";
import { User } from "../../model/User";
import { APP_TYPE } from "../define/EnumDefine";
import { md5 } from "../thirds/md5";

export class ProtoUtil {
    public static sendProto(msgid: number, data?: any) {
        if (NetAdaptor.bAdaptor) {
            NetAdaptor.getInstance().sendMessage(msgid, data);
            return;
        }
        data = data || {};
        js.mixin(data, this.getParam(data));
        let msg = {
            type: msgid,
            message: data,
        };
        NetMgr.Instance().sendMsg = msg;
        NetMgr.Instance().sendDataToLogin();
    }

    static getParam(data?: any) {
        data = data || {};
        if (data["token"] == undefined && User.instance.token != undefined) {
            data["token"] = User.instance.token;
        }
        let stime = Global.svrTimeS;
        data["sign"] = ProtoUtil.getSign(data, stime);
        if (data["stime"] == undefined && stime != undefined) {
            data["stime"] = stime;
        }
        return data;
    }

    static getHttpParam(data?: any) {
        data = data || {};
        let user = User.instance;
        if (!data['token']) {
            data['token'] = user.token || "";
        }
        data['userId'] = user.userId || "";
        data['app_type'] = APP_TYPE.cocos;
        data["isapp"] = 1; //是否app端(1是， 0否）
        let stime = parseInt((Global.svrTimeMS / 1000).toFixed(0));
        data['sign'] = ProtoUtil.getSign(data, stime);
        if (data['stime'] == undefined && stime != undefined) {
            data['stime'] = stime;
        }
        return data;
    }

    static parseToString(data: any): string {
        let list: Array<string> = [];
        for (let key in data) {
            let item = "";
            if (typeof data[key] === 'object') {
                item = JSON.stringify(data[key]);
            } else {
                item = data[key] == undefined ? "" : data[key];
            }
            let text: string = key + "=" + item;
            list.push(text);
        }
        return list.join("&");
    }

    public static parseToObject(text: string): any {
        let data: Object = {};
        if (text == undefined || text == "") {
            return data;
        }
        let list: Array<string> = text.split("&");
        for (let i: number = 0; i < list.length; i++) {
            let item: Array<string> = list[i].split("=");
            data[item[0]] = item[1] == undefined ? "" : item[1];
        }
        return data;
    }

    public static getSign(data: any, stime: number): string {
        let list: Array<string> = [];
        for (let k in data) {
            if (
                data[k] != "undefined" &&
                data[k] != undefined &&
                data[k] != null
            ) {
                list.push(k);
            } else {
                delete data[k];
            }
        }
        list.sort();
        let text: string = "";
        for (let i = 0, len = list.length; i < len; i++) {
            text += data[list[i]];
        }
        text += stime;
        text += Global.SECRET_KEY;

        return new md5().hex_md5(text);
    }
}
