import LogUtil from "../../../common/utils/LogUtil";
import NetHttp, { HTTP_CONTENT_TYPE } from "./NetHttp";
import { HttpRespPack } from "./HttpRespPack";

export default class WebMsgHandler {
    private static url: string = "";
    private static webPara: WebSrc;

    public static init(addr: string) {
        this.url = addr;
    }

    public static setAddr(addr: string) {
        this.url = addr;
    }

    public static sendPost(
        url: string,
        urlData: any,
        objData: any,
        succ: (msg: HttpRespPack, userdata: any) => void,
        fail: (msg: HttpRespPack, userdata: any) => void,
        respThisArg: any,
        encrypt: boolean = false,
        contentType: HTTP_CONTENT_TYPE = HTTP_CONTENT_TYPE.JSON
    ) {
        if (urlData == null) {
            urlData = {};
        }
        let count = 0;
        let sendUrl = url;

        if (!encrypt) {
            Object.keys(urlData).forEach((key) => {
                if (count > 0) {
                    sendUrl += "&";
                } else {
                    sendUrl += "?";
                }
                sendUrl += key + "=" + urlData[key];
                ++count;
            });
        } else {
            let tmpStr = "";
            Object.keys(urlData).forEach((key) => {
                if (count > 0) {
                    tmpStr += "&";
                }
                tmpStr += key + "=" + urlData[key];
                ++count;
            });
            tmpStr = btoa(tmpStr);
            tmpStr += "hello!";
            tmpStr = btoa(tmpStr);
            sendUrl += "?data=";
            sendUrl += tmpStr;
        }

        let dataSucc = (msg: HttpRespPack, userdata: any) => {
            succ && succ(msg, userdata);
        };

        let http = new NetHttp();
        http.init(respThisArg);
        http.sendPost(sendUrl, objData, dataSucc, fail, contentType);
    }

    public static sendGet(
        url: string,
        objData: any,
        succ: (msg: HttpRespPack, userdata: any) => void,
        fail: (msg: HttpRespPack, userdata: any) => void,
        respThisArg: any,
        contentType: HTTP_CONTENT_TYPE = HTTP_CONTENT_TYPE.JSON
    ) {
        let count = 0;
        let sendUrl = url;
        if (objData) {
            Object.keys(objData).forEach((key) => {
                if (count > 0) {
                    sendUrl += "&";
                } else {
                    sendUrl += "?";
                }
                sendUrl += key + "=" + objData[key];
                ++count;
            });
        }
        LogUtil.info("Web数据发送", sendUrl);
        let dataSucc = (msg: HttpRespPack, userdata: any) => {
            succ && succ(msg, userdata);
        };

        let http = new NetHttp();
        http.init(respThisArg);

        http.sendGet(sendUrl, "", dataSucc, fail, contentType);
    }

    static set webSrc(obj: WebSrc) {
        this.webPara = obj;
    }

    /**
     * 解析域名参数
     * @returns WebSrc
     */
    static get webSrc(): WebSrc {
        if (!this.webPara) {
            let search = window.location.search;
            let srh = search.substring(1, search.length);
            // let decode = window.atob(srh);
            // Log.d('window search atob===', decode);
            let searchURL = decodeURIComponent(srh);
            // searchURL = searchURL.substring(1, searchURL.length);
            let str = searchURL;
            this.webPara = new WebSrc(str);
        }
        return this.webPara;
    }
}

export class WebSrc {
    id: string;

    /** 语种 */
    lang: string;

    token: string;

    uid: number;

    cdn: string;

    /** 环境 */
    env: string;

    /** 主界面链接 */
    homeUrl: string;

    /** 币种 */
    currency: string;

    /** 游戏回放 */
    playback: boolean;

    /** 游戏回放code */
    orderNum: string;

    /** 关闭返回功能 */
    closeBack: number;

    /** true: 静音，false: 开启声音，默认：false */
    mute: boolean;

    /** true: 显示货币，false:关闭货币显示, 默认：true */
    currencyDisplay: boolean;

    /** 是否展示玩家id */
    uidDisplay: boolean;

    /** 跳过介绍页 0不跳过 1跳过 */
    skipIntro: number;

    ////服务端debug////
    /** 服 */
    serverDebug: string;
    /** 分 */
    money: string;
    /** 币种 */
    moneyType: string;

    constructor(str: string) {
        let seg = str.split('&'),
            len = seg.length,
            i = 0,
            s;
        for (; i < len; i++) {
            if (!seg[i]) {
                continue;
            }
            s = seg[i].split("=");
            if (s[1] === 'true' || s[1] === 'false') { //bool
                this[s[0]] = s[1] == 'true';
            } else {
                this[s[0]] = s[1];
            }
        }
    }
}