import { Singleton } from "../framework/Singleton";
import i18n from "../framework/language/i18n";


export class GameModel extends Singleton<GameModel>() {

    /** logo播放结束 */
    private _logoPlayed: boolean = false;

    private _popupConfig: any;
    public readPopupCfg(jsonObj: any): void {
        this._popupConfig = jsonObj;
    }
    /**
     * getPopupDataById
     */
    public getPopupDataById(id: number): any {
        if (!this._popupConfig) {
            Log.d(" 没有初始化 _popupConfig ！！ ");
            return null;
        }
        return this._popupConfig[id];
    }
    /**
     * getPopupStrById
     */
    public getPopupStrById(id: number) {
        if (!this._popupConfig) {
            Log.d(" 没有初始化 _popupConfig ！！ ");
            return null;
        }
        let obj = this.getPopupDataById(id);
        if (!obj) {
            return null;
        }
        let str = i18n.tr(obj.i18nId);
        // let mLanguage: string = Global.language;
        // let str: string = obj[mLanguage];
        if (str) {
            return str;
        }
        return null;
    }

    /** logo是否播放结束 */
    public get logoPlayed(): boolean {
        return this._logoPlayed;
    }

    /** logo是否播放结束 */
    public set logoPlayed(isPlayed: boolean) {
        this._logoPlayed = isPlayed;
    }
}