import { Prefab, Asset, director, JsonAsset, sys, resources, SpriteFrame, assetManager, Texture2D, sp } from "cc";
import { ENVIRONMENT, EGAME_TYPE, HttpMethod, StatisticsEvent } from "../common/define/EnumDefine";
import { Macro } from "../common/define/HotUpdateDefine";
import { ResDefine, SoundDefine } from "../common/define/ResDefine";
import { LoginStatistics, NetErrCode } from "../common/define/StatisticsDefine";
import SdkManager from "../common/sdk/SdkManager";
import { ConfigUtil } from "../common/utils/ConfigUtil";
import LogUtil from "../common/utils/LogUtil";
import { LoggerImpl } from "../framework/Logger";
import { eventTrig, StatisticsManager } from "../mgr/StatisticsManager";
import { Singleton } from "../framework/Singleton";
import { UICF, UIID } from "../framework/ui/UIDefined";
import { UIManager, UI_PRELOAD_STR } from "../framework/ui/UIManager";
import UIUtils from "../framework/ui/UIUtils";
import { Global } from "../main/Global";
import { RemoteLoader, ResManager } from "../framework/manager/ResManager";
import { Resource } from "../framework/hall/Resource";
import HotUpdate from "../framework/update/HotUpdate";
import WebMsgHandler from "../common/net/http/WebMsgHandler";
import { EntryManager } from "../framework/hall/entry/EntryManager";
import i18n from "../framework/language/i18n";
import { HttpReqPack } from "../common/net/http/HttpReqPack";
import { HttpRespPack } from "../common/net/http/HttpRespPack";
import { HttpMgr } from "../common/net/http/HttpMgr";
import { GameModel } from "../main/GameModel";
import { GameConst, LOGO_PLAY_TYPE } from "../main/GameConst";

/**加载配置表超时时间 */
const TIME_OUT_CONFIG = 10000;
/**请求失败次数 */
const REQ_FAIL_COUNT = 10;
/**加载资源超时时间 */
const TIME_OUT_RES = 20000;
/**资源加载个数 */
const MAX_LOAD_INDEX = 8;
/**配置表文件名字 */
const FILE_GAME_CONFIG = "game_config_";
const PRELOAD_PREFABS = [
    UIID.UITurnTable,
    UIID.UIQRCode,
    UIID.UIProfile
];

/**
 * 登录加载管理
 */
export class LoadingManager extends Singleton<LoadingManager>() {
    private _loadIndex = 0;
    private loadCb: Function = null;
    private percentCb: Function = null;
    private timeFunc: any = 0;
    private reqCount: number = 0;

    /**
     * 初始化
     */
    init() {
        SdkManager.init();
    }

    /**
     * 加载游戏初始配置
     */
    async loadInitConfig(cb: Function) {
        this.loadCb = cb;
        this.loadIndex = 0;
        this.initGlobal();
        this.initMute();

        let homeUrl = WebMsgHandler.webSrc.homeUrl;
        window['homeUrl'] = Global.homeUrl = decodeURIComponent(homeUrl);

        //加载全局配置
        await this.loadGlobalConfig();
        await this.loadConfig();
        // this.loadIndex++;
        //加载默认语言
        await i18n.init();
        await this.loadAppConfig();
        await this.loadLogoUrls();
        await this.loadAppVerConfig();
        await this.loadCocosVersionConfig();
        await this.loadGameConfig();
        await this.loadPremissionEnter();
        await this.loadComUI();
        this.loadCb && this.loadCb();
    }

    private initGlobal() {
        Global.playback = WebMsgHandler.webSrc.playback;
        Global.playbackId = WebMsgHandler.webSrc.orderNum || '';
        Global.gameId = Number(WebMsgHandler.webSrc.id || '0');
        Global.gameType = this.getGameType();
        Global.userId = WebMsgHandler.webSrc.uid || 0;
        Global.token = WebMsgHandler.webSrc.token || '';
        Global.platformId = Number(WebMsgHandler.webSrc.env);
        Global.language = WebMsgHandler.webSrc.lang || Global.language;
        Global.closeBack = Number(WebMsgHandler.webSrc.closeBack || '0');
        Global.currencyDisplay = WebMsgHandler.webSrc.currencyDisplay == undefined ? Global.currencyDisplay : WebMsgHandler.webSrc.currencyDisplay;
        Global.uidDisplay = WebMsgHandler.webSrc.uidDisplay == undefined ? Global.uidDisplay : WebMsgHandler.webSrc.uidDisplay;
        Global.mute = WebMsgHandler.webSrc.mute == undefined ? Global.mute : WebMsgHandler.webSrc.mute;
        Global.skipIntro = Number(WebMsgHandler.webSrc.skipIntro || '0');
    }

    /** 初始化是否静音 */
    private initMute() {
        Global.backgroundMusic = !Global.mute;
        Global.soundEffect = !Global.mute;
    }

    /**
     * 登录加载
     */
    async load(cb: Function) {
        this.percentCb = cb;
        this.setLoadTimeOut(TIME_OUT_RES);
        this.init();
        //加载其他资源
        StatisticsManager.getInstance().loginReport(LoginStatistics.loadStart);
        StatisticsManager.getInstance().setStartTime(LoginStatistics.loadTimes);
        eventTrig(StatisticsEvent.LOADED_RES_START);
        //加载配置
        await this.loadConfig();
        this.loadIndex++;
        //直接加载主场景信息
        director.preloadScene("MainScene", () => {
            this.loadIndex++;
        });
        //加载语言包
        // I18n.getInstance().language.loadLanguage();

        //加载登录 prefab
        ResManager.Instance().load(
            Macro.BUNDLE_RESOURCES,
            ResDefine.UI_PREFAB_URL + "UILoginFull",
            Prefab,
            () => { },
            () => {
                this.loadIndex++;
            }
        );
        //加载vp主界面库里的所有图像资源
        ResManager.Instance().loadDir(
            Macro.BUNDLE_RESOURCES,
            ResDefine.VP_GAME_LOCATION,
            Asset,
            () => { },
            () => {
                this.loadIndex++;
            }
        );
    }

    /**
     * 加载进度
     */
    set loadIndex(index: number) {
        index = index >= MAX_LOAD_INDEX ? MAX_LOAD_INDEX : index;
        this._loadIndex = index;
        if (this.percentCb) {
            this.percentCb(index / MAX_LOAD_INDEX);
        }
        if (this.loadIndex >= MAX_LOAD_INDEX) {
            if (this.timeFunc) clearTimeout(this.timeFunc);
        }
        UIUtils.closeTips();
    }

    /**
     * 设置加载超时处理
     */
    setLoadTimeOut(time: number, cb?: Function) {
        if (this.timeFunc) clearTimeout(this.timeFunc);
        this.timeFunc = setTimeout(() => {
            this.loadFail(cb);
        }, time);
    }

    /**
     * 加载失败处理
     */
    loadFail(cb?: Function) {
        Log.e(`load res fail! loadIndex=${this.loadIndex}`);
        this.reqCount = 0;
        let code = this.loadIndex >= 3 ? 3 : this.loadIndex;
        UIUtils.netErrorTips(NetErrCode.loadFail + code, () => {
            if (HotUpdate.getInstance().updating) return;
            if (cb) cb();
            else this.load(this.percentCb);
        });
        eventTrig(StatisticsEvent.LOADED_RES_FAIL);
    }

    get loadIndex() {
        return this._loadIndex;
    }

    /**
     * 加载全局配置
     */
    async loadGlobalConfig() {
        return new Promise((resolve, reject) => {
            ResManager.Instance().load(
                Macro.BUNDLE_RESOURCES,
                ResDefine.GLOBAL_CONFIG_LOCATION,
                JsonAsset,
                () => { },
                (res: Resource.CacheData) => {
                    let data: any = res.data!;
                    let json = data.json;
                    // Global.gameId = GamesData.gameId = json["gameId"];

                    Global.debug = json["debug"] === "false" ? false : true;
                    Global.platform = json['platform'];

                    LoggerImpl.getInstance().init(Global.debug);
                    LogUtil.init(Global.debug);

                    resolve(null);
                }
            );
        });
    }

    /**
     * 加载配置表
     */
    async loadConfig() {
        return new Promise((resolve) => {
            ResManager.Instance().load(
                Macro.BUNDLE_RESOURCES,
                ResDefine.CONFIG_LOCATION,
                JsonAsset,
                () => { },
                (res: Resource.CacheData) => {
                    let data: any = res.data!;
                    let json = data.json;
                    ConfigUtil.init(json);
                    resolve(null);
                }
            );
        });
    }

    /**
     * 加载app网络配置
     */
    async loadAppConfig(cb?: Function) {
        return new Promise(async (resolve, reject) => {
            let initReqSucc = (res: any) => {

                if (WebMsgHandler.webSrc.serverDebug)
                    Global.wssSvr = WebMsgHandler.webSrc.serverDebug; //服务端debug
                else
                    Global.wssSvr = res.game_url;
                Global.webSocket = `${Global.wssSvr}/websocket1`
                Log.d(`===Global.wssSvr===${Global.wssSvr}`)
                Log.d(`===Global.webSocket===${Global.webSocket}`)  

                Global.gameShortSvr = res.game_short_url;
                Global.httpSvr = res.back_url;
                Global.gbsSvr = res.gbs_url;
                Global.cdn = res.cdn;

                Log.d(`===initReqSucc===${JSON.stringify(res)}`)
                if (cb) cb();
                resolve(null);
            };

            let time = Date.now();
            let url = Global.cUrl;
            let name = this.configjsonName();
            url = `${url}/${name}.json?t=${time}`;
            Log.d(`###loadRemoteJson url ##${url}###`);
            await RemoteLoader.Instance().loadRemoteJson(url).then((data: any) => {
                Log.d("loadRemoteJson data:" + data.json);
                if (data && data !== "") {
                    initReqSucc(data.json);
                }
            }).catch(() => { });
        });
    }

    /**
     * app网络配置文件名
     * @returns 
     */
    private configjsonName(): string {
        let name = Global.debug ? '192.168.100.4' : window.location.host;
        switch (Global.platformId) {
            case ENVIRONMENT.EXHI:
                name = `vp${Global.platformId}`; break;
            case ENVIRONMENT.DEV:
            case ENVIRONMENT.STA:
                name = `${name}-vp9990${Global.platformId}`; break;
        }
        // console.log('#file name', window.location);
        console.log('###file name', name);
        name = 'vp999gamecdn.vmight999.xyz';        //配置服务器接口地址，稳定服和测试服
        // name = 'wild-devclient.games666.xyz';
        // name = 'wild-stabclient.games666.xyz';
        return name;
    }

    /** 
     * 加载logo url
     */
    async loadLogoUrls() {
        return new Promise(async (resolve, reject) => {
            if (WebMsgHandler.webSrc.serverDebug) {
                resolve(null);
                return;
            }
            let data: any = {};
            if (Global.playback) {
                data = {
                    gameId: Global.gameId,
                    code: Global.playbackId
                }
            } else {
                data = {
                    token: Global.token
                }
            }
            let pack: HttpReqPack = HttpReqPack.create(`/api/v1/plat/info/logo`, JSON.stringify(data), HttpMethod.POST);
            await HttpMgr.Instance().send(pack, null, (param: HttpRespPack) => {
                let data: HttpRespPack = param;
                Global.logoUrls = data.data.logoUris;
                Global.logoType = data.data.logoType;
                resolve(null);
            })
        });
    }

    /**
     * 加载游戏配置
     * 游戏版本
     */
    async loadAppVerConfig() {
        return new Promise(async (resolve, reject) => {
            let url = `${Global.cdn}/${GameConst.APP_GAMES_CONFIG}?v=${Global.svrTimeMS}`
            await RemoteLoader.Instance()
                .loadRemoteJson(url)
                .then((data: any) => {
                    let jsonMinor = data.json;
                    if (jsonMinor) {
                        Global.appVersion = jsonMinor.version;
                    }
                    resolve(null);
                })
        })
    }

    /**加载客户端游戏数据配置*/
    async loadCocosVersionConfig() {
        return new Promise(async (resolve, reject) => {
            // eventTrig(StatisticsEvent.LOADED_CONFIG_START);
            // let url = `${Global.cdn}/gamec/gameupdate/games_version.json?v=${Global.svrTimeMS}`
            // let url = `http://192.168.100.4/vp99902/gamec/gameupdate/games_version.json?v=${Global.svrTimeMS}`;
            let url = `https://vp999gamecdn.vmight666.xyz/gamec/gameupdate/games_version.json?v=${Global.svrTimeMS}`;
            Log.d('===loadCocosVersionConfig===', url);
            await RemoteLoader.Instance()
                .loadRemoteJson(url)
                .then((data: any) => {
                    Log.d("loadGameVersion,data:" + data.json);
                    let jsonMinor = data.json;
                    LogUtil.debug("loadClientPara2," + JSON.stringify(jsonMinor));
                    if (jsonMinor) {
                        for (let key in jsonMinor) {
                            EntryManager.getInstance().initBundlesVersion(jsonMinor[key]);
                        }
                    }
                    resolve(null);
                })
        });
    }


    /** 加载本地json文件 */
    async loadGameConfig() {
        return new Promise(async (resolve) => {
            // eventTrig(StatisticsEvent.LOADED_CONFIG_START);
            let url = `config/PopupConfig`;
            Log.d('===loadGameConfig===', url);
            await ResManager.Instance().load(Macro.BUNDLE_RESOURCES, url, JsonAsset, () => { }, (evt: any) => {
                GameModel.getInstance().readPopupCfg(evt.data.json);
                resolve(null);
            });
        })
    }

    /** 加载后台接口是否有权限进入游戏 */
    async loadPremissionEnter() {
        return new Promise(async (resolve) => {
            if (Global.playback) {
                resolve(null);
                return;
            }
            if (WebMsgHandler.webSrc.serverDebug) {
                resolve(null);
                return;
            }

            let data = {
                gameId: Global.gameId,
                token: Global.token,
                language: Global.language,
                uid: Global.userId
            };
            let pack: HttpReqPack = HttpReqPack.create(`/api/player/auth/openGame`, JSON.stringify(data), HttpMethod.POST);
            await HttpMgr.Instance().send(pack, null, (param: HttpRespPack) => {
                let data: HttpRespPack = param;
                if (data.data && data.data.result)
                    Global.premissionToEnterGame = true;
                else
                    Global.premissionToEnterGame = false;
                Global.premissionEnterGameCode = data.data.reason;
                resolve(null);
            })
        })
    }

    /**
     * 预加载通用UI
     * @description 防止玩家断线，获取不到popup资源
     * @returns resolve
     */
    async loadComUI() {
        return new Promise(async (resolve) => {
            let popup = UICF[UIID.UIPopup];
            resources.load(popup.prefab, (...param) => {
                let arg = param;
            }, (...param) => {
                let arg = param;
                resolve(null);
            });
        })
    }

    /**游戏分类 1:公共资源包 2:捕鱼  3:老虎机  4:其他游戏 */
    public getGameType(): EGAME_TYPE {
        let str = Global.gameId.toString();
        let st = Number(str.slice(0, 1));
        if (st == 1) return EGAME_TYPE.FISHING;
        else if (st == 3) return EGAME_TYPE.SLOTS;
        return EGAME_TYPE.MO_GAME;
    }
}
