import { SocketBase, SocketEvent } from "./SocketBase";

enum TencentSocketState {
	Init = "Init",
	Connected = "Connected",
	Closed = "Closed",
	Error = "Error",
}

class TencentSocket extends SocketBase {
	private _socketInstance: any = null!;

	private _state: TencentSocketState = null!;
	public get state() {
		return this._state;
	}

	constructor(url: string) {
		super(url);
		this._state = TencentSocketState.Init;
	}

	connect(): void {
		this._socketInstance = qq.connectSocket({
			url: this._url,
			header: {
				"content-type": "application/json",
			},
		});
		this._socketInstance.onOpen(this._onOpen.bind(this));
		this._socketInstance.onMessage(this._onMessage.bind(this));
		this._socketInstance.onClose(this._onClose.bind(this));
		this._socketInstance.onError(this._onError.bind(this));
	}

	send(message: string | ArrayBuffer) {
		this._socketInstance.send({ data: message });
	}

	close() {
		this._state = TencentSocketState.Closed;
		this._socketInstance.close();
	}

	getState() {
		return this._state;
	}

	private _onOpen(data: { header: any }): void {
		this._state = TencentSocketState.Connected;
		this.dispatch(SocketEvent.Open, data);
	}

	private _onMessage(message: { data: string | ArrayBuffer }): void {
		this.dispatch(SocketEvent.Message, message.data);
	}

	private _onClose(): void {
		Log.w(`Socket Close, ${this}`);
		this._state = TencentSocketState.Closed;
		this.dispatch(SocketEvent.Close);
	}

	private _onError(message: { errMsg: string }): void {
		Log.w(`Socket Error, reason: ${message.errMsg}, ${this}`);
		this._state = TencentSocketState.Error;
		this.dispatch(SocketEvent.Error, message);
	}
}

export { SocketEvent, TencentSocketState, TencentSocket };
