import { AssetManager } from "cc";
import { Eventer } from "../../Eventer";
import { HotUpdateManager } from "../../update/HotUpdateManager";
import { HotUpdate } from "../../update/IHotUpdate";
import { BundleManager } from "../../manager/BundleManager";
import { BUNDLE_RESOURCES, ENTRY_CONFIG } from "../HallDefind";
import { Entry } from "./Entry";
import { EntryManager } from "./EntryManager";
import { ELOADER_STATE } from "../../../common/define/EnumDefine";

/** entry入口代理 */
export class EntryDelegate {
    /** 当前有正在加载中的bundle */
    onBundleLoading(versionInfo: HotUpdate.BundleConfig) {
        Log.d("正在更新...");
    }

    /** 发现新版本 */
    onNewVersionFund(
        versionInfo: HotUpdate.BundleConfig,
        code: HotUpdate.Code
    ) {
        HotUpdateManager.getInstance().hotUpdate();
    }

    /** 下载失败 */
    onDownloadFailed(
        versionInfo: HotUpdate.BundleConfig,
        code: HotUpdate.Code,
        state: HotUpdate.State
    ) {
        HotUpdateManager.getInstance().downloadFailedAssets();
    }

    /** 当前已经是新包，无需更新 */
    onAreadyUpToData(
        versionInfo: HotUpdate.BundleConfig,
        code: HotUpdate.Code,
        state: HotUpdate.State
    ) {
        BundleManager.getInstance().loadBundle(this, versionInfo.bundle);
    }

    /** 下载版本文件失败 */
    onDownloadManifestFailed(
        versionInfo: HotUpdate.BundleConfig,
        code: HotUpdate.Code,
        state: HotUpdate.State
    ) {
        let content = '下载版本文件失败!';
        if (code == HotUpdate.Code.ERROR_NO_LOCAL_MANIFEST) {
            content = '找不到版本文件!';
        } else if (code == HotUpdate.Code.ERROR_PARSE_MANIFEST) {
            content = '版本文件解析错误!';
        }
        Log.w(content);
    }

    /** 正在检测更新 */
    onCheckingVersion(
        versionInfo: HotUpdate.BundleConfig,
        code: HotUpdate.Code,
        state: HotUpdate.State
    ) {
        //do nothing
    }

    /** 其它错误 */
    onOtherReason(
        versionInfo: HotUpdate.BundleConfig,
        code: HotUpdate.Code,
        state: HotUpdate.State
    ) {
        //do nothing
    }

    /** 资源下载中 */
    onDownloading(versionInfo: HotUpdate.BundleConfig, info: HotUpdate.DownLoadInfo) {
        let newPercent = 0;
        if (info.code == HotUpdate.Code.UPDATE_PROGRESSION) {
            if (!info.percent || info.percent <= 0) return;
            newPercent = info.percent >= 100 ? 100 : info.percent;
            Log.d(`===onDownloading===${versionInfo.bundle},${versionInfo.name}, ${versionInfo.gameId}===`)
            Eventer.getInstance().emit(HotUpdate.Event.DOWNLOAD_PROGRESS, {
                id: versionInfo.gameId,
                delta: newPercent,
                state: ELOADER_STATE.DOWNLOADING
            });
        } else if (info.code == HotUpdate.Code.ALREADY_UP_TO_DATE) {
            versionInfo.hasUpdate = false;
            if (BundleManager.getInstance().downloadingId == versionInfo.gameId) {
                BundleManager.getInstance().loadBundle(this, versionInfo.bundle);
            }
        } else if (info.code == HotUpdate.Code.UPDATE_FINISHED) {
            versionInfo.hasUpdate = false;
            BundleManager.getInstance().loadBundle(this, versionInfo.bundle);
            // Eventer.getInstance().emit(HotUpdate.Event.DOWNLOAD_PROGRESS, {
            //     id: versionInfo.gameId,
            //     state : ELOADER_STATE.FINISH
            // });
        } else if (
            info.code == HotUpdate.Code.UPDATE_FAILED ||
            info.code == HotUpdate.Code.ERROR_NO_LOCAL_MANIFEST ||
            info.code == HotUpdate.Code.ERROR_DOWNLOAD_MANIFEST ||
            info.code == HotUpdate.Code.ERROR_PARSE_MANIFEST ||
            info.code == HotUpdate.Code.ERROR_DECOMPRESS
        ) {
            Log.w(`===资源下载失败！=====`)
        }
    }

    /** 加载Bundle错误 */
    onLoadBundleError(versionInfo: HotUpdate.BundleConfig, err: Error) {
    }

    /** 加载bundle完成 */
    onLoadBundleComplete(versionInfo: HotUpdate.BundleConfig, bundle: AssetManager.Bundle) {
        //通知入口管理进入bundle
        // UIUtils.hideLoading()
        EntryManager.getInstance().onLoadBundleComplete(versionInfo, bundle);
    }

    /** 进入bundle完成 */
    onEnterBundle(entry: Entry | null) {
        //删除除自己之外的其它bundle
        let excludeBundles = [];
        let persists = this.getPersistBundle();
        excludeBundles = excludeBundles.concat(persists);
        if (entry && excludeBundles.indexOf(entry.bundle) == -1) {
            excludeBundles.push(entry.bundle);
        }

        BundleManager.getInstance().removeLoadedBundle(this, excludeBundles);
    }

    /** 主包检测更新 */
    onCheckUpdate() {
        let config = new HotUpdate.BundleConfig(BUNDLE_RESOURCES, BUNDLE_RESOURCES);
        BundleManager.getInstance().enterBundle(config, this);
    }

    /** 获取常驻于内存不释放的bundle */
    getPersistBundle() {
        return EntryManager.getInstance().persistBundles;
    }

    getEntryConfig(bundle: string): HotUpdate.BundleConfig | null {
        let config = ENTRY_CONFIG[bundle];
        if (config) {
            return config;
        }

        Log.d(`未找到入口配置信息:${bundle}`);
        return null;
    }
}
