
export default class TimeUtil {

    public static DAY_TIME_LEN: number = 24 * 60 * 60;

    /**
 * 获得当前毫秒时间
 */
    public static getCurMilliTime(): number {
        return new Date().getTime();
    }

    /**
     * 获得当前秒时间
     * @param isInt 
     */
    public static getCurSecondTime(isInt: boolean = true): number {
        let res = new Date().getTime() / 1000;
        return isInt ? Math.floor(res) : res;
    }

    /**
     * 秒数转字符串
     * @param mSec 秒 
     * @returns 字符 00:00:00
     */
    public static secondTimeStr(mSec: any): string {
        let t = '';

        if (mSec <= 0) {
            return '00:00:00';
        }

        // let sec = ms / 1000;
        let hour = Math.floor(mSec / 3600);
        let min = Math.floor((mSec / 60) % 60);
        let sec = Math.floor(mSec % 60);
        if (hour < 10) {
            t = '0' + hour + ":";
        } else {
            t = hour + ":";
        }
        if (min < 10) {
            t += "0";
        }
        t += min + ":";
        if (sec < 10) {
            t += "0";
        }
        t += sec.toFixed(0);

        if (t == '') {
            return '00:00:00';
        }
        return t;
    }


    //根据格式（默认YYYY-MM-dd HH:mm:ss)获得对应的时间
    public static dateFormat(timeStampe: number, fmt: string = 'YYYY-MM-dd HH:mm:ss'): string {
        let ret;
        let date = new Date(timeStampe * 1000);
        const opt: any = {
            "Y+": date.getFullYear().toString(),        // 年
            "M+": (date.getMonth() + 1).toString(), //月份 
            "d+": date.getDate().toString(), //日 
            "H+": date.getHours().toString(), //小时 
            "m+": date.getMinutes().toString(), //分 
            "s+": date.getSeconds().toString(), //秒 
            "q+": (Math.floor((date.getMonth() + 3) / 3)).toString(), //季度 
            "S": (date.getMilliseconds()).toString() //毫秒
        };
        for (let k in opt) {
            ret = new RegExp("(" + k + ")").exec(fmt);
            if (ret) {
                fmt = fmt.replace(ret[1], (ret[1].length == 1) ? (opt[k]) : (opt[k].padStart(ret[1].length, "0")))
            };
        };
        return fmt;
    }
    //格式化日期: yyyy-mm-dd
    public static formatDate(date: Date) {
        return this.timeStamp2String(date.getTime(), "yyyy-MM-dd");
    }
    /**
    * 格式化日期
    * @param stamp 时间戳 相对1970年的毫秒数
    * @param format 格式化
    */
    public static timeStamp2String(stamp: number, format: string = "yyyy/MM/dd hh:mm:ss"): string {
        let date = new Date(stamp);
        let info = {
            "M+": date.getMonth() + 1,
            "d+": date.getDate(),
            "h+": date.getHours(),
            "m+": date.getMinutes(),
            "s+": date.getSeconds(),
            "q+": Math.floor((date.getMonth() + 3) / 3),
        };
        if (/(y+)/i.test(format)) {  //年份格式化
            format = format.replace(RegExp.$1, (date.getFullYear() + "").substr(4 - RegExp.$1.length));
        }
        if (/(S+)/.test(format)) {  //毫秒数格式化
            let ms = ("000" + date.getMilliseconds()).substr(-3);
            format = format.replace(RegExp.$1, ms.substr(0, RegExp.$1.length));
        }

        for (let key in info) {
            if (new RegExp("(" + key + ")").test(format)) {
                format = format.replace(RegExp.$1, RegExp.$1.length == 1 ?
                    info[key] : ("00" + info[key]).substr(("" + info[key]).length));
            }
        }
        return format;
    }

}
