import { UNKNOWN } from "../HallDefind";

/** 游戏内数据的公共基类 */
export abstract class GameData {
    static bundle = UNKNOWN;

    /** 数据所有bundle，由数据中心设置 */
    bundle: string = "";

    /** 游戏开始时间 */
    static gameStartTime: number;

    /** 玩家第一次点击 */
    static firstClick: boolean = false;

    /** 清除数据 */
    clear() { }
}