export interface ISocket {
	connect();
	send(data: string | ArrayBuffer);
	close();
	getState();
}

export enum SocketEvent {
	Open = "SocketOpen",
	Message = "SocketMessage",
	Close = "SocketClose",
	Error = "SocketError",
	ReLogin = "ReLogin"
}

export enum SocketState {
	CONNECTING = 1,
	OPEN,
	CLOSING,
	CLOSED,
}

export interface ISocketDelegate {
	onSocketOpen();
	onSocketMessage(data: string | ArrayBuffer);
	onSocketError(errMsg);
	onSocketClosed(msg: string);
}

export type ListenerObject = {
	listenerID: number;
	listener: Function;
	isValid: boolean;
};

export type SocketListeners = {
	[SocketEvent.Open]: Array<ListenerObject>;
	[SocketEvent.Message]: Array<ListenerObject>;
	[SocketEvent.Close]: Array<ListenerObject>;
	[SocketEvent.Error]: Array<ListenerObject>;
};

export class SocketBase implements ISocket {
	public _url: string;
	private _listenerIDCounter: number = -1;
	private _listeners: SocketListeners = null!;

	constructor(url: string) {
		this._url = url;
		this._listeners = {
			[SocketEvent.Open]: [],
			[SocketEvent.Message]: [],
			[SocketEvent.Close]: [],
			[SocketEvent.Error]: [],
		};
		this._listenerIDCounter = -1;
	}

	connect() {
		throw new Error("Method not implemented.");
	}
	send(data: string | ArrayBuffer) {
		throw new Error("Method not implemented.");
	}
	close() {
		throw new Error("Method not implemented.");
	}
	getState() {
		throw new Error("Method not implemented.");
	}

	public addListener(event: SocketEvent, listener: Function): number {
		if (!this._listeners[event]) {
			return -1;
		}

		this._listeners[event].push({
			listenerID: this._listenerIDCounter++,
			listener: listener,
			isValid: true,
		});
		return this._listenerIDCounter;
	}

	public removeListenerByEvent(event: SocketEvent): void {
		if (!this._listeners[event]) {
			return;
		}

		for (let i = 0; i < this._listeners[event].length; ++i) {
			this._listeners[event][i].isValid = false;
		}
	}

	public removeListenerByID(listenerID: number): void {
		for (let event in this._listeners) {
			for (let i = 0; i < this._listeners[event].length; ++i) {
				if (this._listeners[event][i].listenerID === listenerID) {
					this._listeners[event][i].isValid = false;
					return;
				}
			}
		}
	}

	public removeAllListener() {
		for (let event in this._listeners) {
			this._listeners[event] = [];
		}
	}

	public dispatch(event: SocketEvent, param: any = undefined): void {
		let newList: Array<ListenerObject> = [];
		for (let i = 0; i < this._listeners[event].length; ++i) {
			if (!this._listeners[event][i].isValid) {
				continue;
			}
			this._listeners[event][i].listener(param);
			newList.push(this._listeners[event][i]);
		}
		this._listeners[event] = newList;
	}
}
