    /**
     * 千分位格式化整数
     * @param val
     */
    private static formatDigitByTHS(val: number | string): string {
        val = val + "";
        let reg = /(\d)(?=(?:\d{3})+$)/g;
        val = val.replace(reg, "$1,");
        return val;
    }

    /**
     * 合成格式化字符串
     * @param pre 整数部份
     * @param decimal 小数部份
     * @param precision 精度
     */
    private static formateNumToStr(pre: string, decimal: string, precision: number) {
        let str = precision > 0 ? pre + "." : pre;
        decimal = decimal ? decimal.split(".")[1] || "" : "";
        for (let i = 0; i < precision; i++) {
            str = str + (decimal[i] || "0");
        }
        return str;
    }

    /**
     * 精度合成字符串
     * @param precision 精度
     */
    private static createZeroPrecision(precision: number): string {
        let str = precision > 0 ? "0." : "0";
        for (let i = 0; i < precision; i++) {
            str += "0";
        }
        return str;
    }

    /*
    * formatMoney(s,type)
    * 功能：金额按千位逗号分割
    * 参数：s，需要格式化的金额数值.
    * 返回：返回格式化后的数值字符串.
    */
    public static formatMoney(money: string | number): string {
        let point = Global.point;
        let ths = Global.thousandPoint;
        money = money + "";
        if (!StringUtil.checkNum(money)) {
            return GameUtils.createZeroPrecision(point);
        }
        let numArr = money.split(".");
        let integer = ths ? GameUtils.formatDigitByTHS(numArr[0]) : numArr[0];
        let decimal = fixedDigital(Number("0." + (numArr[1] || "0"))) + "";
        let str = GameUtils.formateNumToStr(integer, decimal, point);
        return str;
    }

    public static isClass(o) {
        if (o === null) return "Null";
        if (o === undefined) return "Undefined";
        return Object.prototype.toString.call(o).slice(8, -1);
    }

    // 普通Object数据的复制
    public static copyTab(st: any) {
        if (st == null) return null;
        let tab: any;
        let objType = GameUtils.isClass(st);
        if (objType == "Object") {
            tab = {};
            for (let k in st) {
                tab[k] = GameUtils.copyTab(st[k]);
            }
        } else if (objType == "Array") {
            tab = [];
            st.forEach((v, i) => {
                tab.push(GameUtils.copyTab(v));
            });
        } else {
            tab = st;
        }
        return tab;
    }

