    /**
    * 替换占位符
    * @param str 字符串，占位符用{0}{1}...形式
    * @param params 需要替换的变量 
    * @returns 
    */
    public static replaceString(str: string, params: any[]) {
        let result = str;
        if (params && params.length > 0) {
            for (let i: number = 0; i < params.length; i++) {
                let replaceStr: RegExp = new RegExp(`\\{${i}\\}`, "g");
                let tempStr: string = params[i];
                result = result.replace(replaceStr, tempStr);
            }
        }
        return result;
    }

    /**
     * 获取横竖屏状态
     * @returns landscape 横屏 portrait 竖屏
     */
    public static getScreensMode() {
        let status = 'landscape'
        if (window.matchMedia('(orientation: portrait)').matches) {
            status = 'portrait'
        }
        return status
    }

    /**
     * 埋点接口
     * @param key 
     * @param data 
     * @returns 
     */
    public static c2javaMarkByShort(key, data) {
        if (Global.debug)
            return;
        if (Global.playback)
            return;
        let event = {
            type: key,
            token: Global.token,
            timestamp: Date.now(),
            data: data
        };
        let body = {
            event: '',
            sign: ''
        }
        body.event = JSON.stringify(event);
        body.sign = new md5().hex_md5(body.event);
        let json = JSON.stringify(body);
        let pack: HttpReqPack = HttpReqPack.create(`/api/buried/report`, json, HttpMethod.POST);
        HttpMgr.Instance().send(pack);
    }

