/**
 * 修改数字精度
 * @param score
 */
export function fixedDigital(score: number): number {
    let num = Math.floor(score);
    if (score >= 1) {
        score = score - num;
    }
    let fixed = Math.pow(10, Global.point + 1);
    score = num + (score * fixed / 10 >> 0) * 10 / fixed;
    return score;
}
