
import { _decorator, Asset, sys, Component, Label, ProgressBar } from "cc";
import DStorage from "../framework/DStorage";
import HotUpdate, { UpdateParams } from "../framework/update/HotUpdate";
import { UILoadingMain } from "./UILoadingMain";
import UIUtils from "../framework/ui/UIUtils";
import { Global } from "../main/Global";
import { LoginStatistics } from "../common/define/StatisticsDefine";
import { StatisticsManager } from "../mgr/StatisticsManager";
import { LoadingManager } from "./LoadingManager";
import i18n from "../framework/language/i18n";

const { ccclass, property } = _decorator;
const key_userId = "USERID";
const key_deviceid = "deviceid";
const key_spaceId = "spaceId";

@ccclass("HotUpdateView")
export default class HotUpdateView extends Component {
    /**版本资源信息文件 */
    @property(Asset)
    mainifest: Asset = null;
    @property(Label)
    labelVersion: Label = null;
    @property({ displayName: "进度条", type: ProgressBar })
    progressBar: ProgressBar = null!;
    @property({ displayName: "进度条label", type: Label })
    progressLabel: Label = null!;

    start() {
        LoadingManager.getInstance().loadInitConfig(this.checkHotUpdate.bind(this));
    }

    /** 
     * 检查更新
     * @returns 
     */
    checkHotUpdate() {
        if (sys.getNetworkType() == sys.NetworkType.NONE) {
            setTimeout(() => {
                this.onFailTips();
            }, 500);
            return;
        }
        if (!sys.isNative) {
            this.enterGame();
            return;
        }
        this.setProgress(0);
        let hotUpdate = HotUpdate.getInstance();
        let _this = this;
        this.progressBar.node.active = true;
        this.setTips('The Game is updating');
        let params: UpdateParams = {
            asset: this.mainifest,
            onUpdate: function (isNeedUpdate: boolean) {
                if (!isNeedUpdate) {
                    _this.enterGame();
                } else {
                    _this.progressBar.node.active = true;
                    StatisticsManager.getInstance().loginReport(LoginStatistics.updateStart);
                    StatisticsManager.getInstance().setStartTime(LoginStatistics.updateTimes);
                }
            },
            onProgress: function (isSuccess: boolean, percent?: number, tips?: string) {
                if (percent) {
                    _this.setProgress(percent);
                }
                if (tips) {
                    _this.setTips(tips);
                }
                if (isSuccess) {
                    _this.setTips('The Game is updating!!!');
                    StatisticsManager.getInstance().loginReport(LoginStatistics.updateSuccess);
                    StatisticsManager.getInstance().loginReport(LoginStatistics.updateTimes, true);
                    _this.enterGame();
                }
            },
            onFail: _this.onFailTips.bind(_this),
            whiteParams: {
                uid: DStorage.get(key_userId),
                spaceId: DStorage.get(key_spaceId),
                deviceid: DStorage.get(key_deviceid)
            },
        };
        hotUpdate.init(Global.platformId, Global.cdn);
        hotUpdate.checkUpdate(params);
    }

    setTips(str: string) {
        if (this.progressLabel) {
            this.progressLabel.string = str;
        }
    }

    setProgress(progressNumber: any) {
        if (this.progressBar) {
            this.progressBar.progress = progressNumber;
        }
    }

    enterGame() {
        this.progressBar.node.active = true;
        this.labelVersion.string = Global.appVersion;
        this.node.getComponent(UILoadingMain)!.loadRes(this);
    }

    onFailTips(errCode?: number) {
        UIUtils.netErrorTips(errCode, () => {
            this.checkHotUpdate();
        });
    }
}
