import { Global } from "../../main/Global";
import { i18nConfig } from "./i18nConfig";

export class i18nUtils {

    public static tr(code: number, ...args): string {
        let config = i18nConfig.main[code];
        if (!config) {
            console.error('The corresponding text information cannot be obtained!')
            return;
        }
        let text = config['cn'];
        if (!text) {
            console.error('Text information in the corresponding language cannot be obtained!')
            return;
        }

        if (!text) {
            return "{" + code + "}";
        }

        let length = args.length;
        for (let i = 0; i < length; i++) {
            text = text.replace("{" + i + "}", args[i]);
        }
        return text;
    }
}