@ccclass('CtrlBase')
export class CtrlBase extends Component {
    // [1]
    // dummy = '';

    // [2]
    // @property
    // serializableDummy = 0;

    protected start() {
        // [3]
    }
    getUserInfo(): User {
        return User.instance;
    }
    getModel<T extends Controller>(classRef: { prototype: T }) {

        let _classRef: any = classRef;
        // let className = _classRef.prototype.__classname__;
        // let className = _classRef.name;
        let className = js.getClassName(classRef);
        // let className = getClassName(classRef);
        // LogUtil.debug("getModel classRef:"+classRef);
        // LogUtil.debug("getModel classname:"+className);
        let instance: T = Global.modelMap[className];
        if (instance == null) {
            return this.addModel<T>(new _classRef as T, className) as T;
        }
        return instance;
    }

    //---------------------------------------
    //以下是数据管理器单例
    //---------------------------------------
    /**
     * 添加单例实例
     * @param model 单例实例
     * @return <T extends egret.IEventDispatcher>
     */
    protected addModel<T extends Controller>(model: T, className: string): T {
        // let className = getClassName(model);

        // let _model: any = model;
        // let className = _model.prototype.__classname__;
        // let className = _model.name;
        let instance: T = Global.modelMap[className];
        if (instance == null) {
            instance = model;
            Global.modelMap[className] = instance;
        } else {
            throw new Error("[" + className + "]在MVC中已经存在该单例对象！");
        }
        return instance;
    }
    // update (deltaTime: number) {
    //     // [4]
    // }
}

