import { HttpMethod } from './../../define/EnumDefine';

import StringUtil from "../../utils/StringUtil";
import { HttpResponseType, URLLoaderDataFormat } from '../../define/StructDefine';

/**
 * HTTP请求的信息
 */
export class HttpReqPack {

    /**
     * 接口
     */
    private _key: string = "";
    /**
     * 请求方式
     */
    public method: string = "";
    /**
     * 返回的数据格式：egret.HttpResponseType中的值，一般数据交互都是用egret.HttpResponseType.TEXT
     */
    public respFormat: string = "";
    /**
     * 键值对形式:{key:value, key:value}
     */
    public data: any;

    public reqFormat: string = "";

    /**
     * 直接获取并为一个HttpReqMsg赋值
     * @param key
     * @param data 如果reqFormat参数不为二进制数据，则将reqFormat的键值对形式:{key:value, key:value}转换为 key=value&key=value 的HTTP参数形式
     * @param method
     * @param respFormat
     * @param reqFormat
     */
    public static create(key: string, data: any = null, method: string = HttpMethod.POST, respFormat: string = HttpResponseType.TEXT, reqFormat: string = URLLoaderDataFormat.TEXT): HttpReqPack {
        // public static create(key: string,  data:any = null, method:string = egret.HttpMethod.POST, respFormat:string = egret.HttpResponseType.ARRAY_BUFFER, reqFormat:string = egret.URLLoaderDataFormat.TEXT):HttpReqPack{
        // return this._cachePool.pop(HttpReqPack, key, method, data, respFormat, reqFormat) as HttpReqPack;
        let httpReqPack = new HttpReqPack;
        httpReqPack.key = key;
        httpReqPack.data = data;
        httpReqPack.method = method;
        httpReqPack.respFormat = respFormat;
        httpReqPack.reqFormat = reqFormat;
        return httpReqPack;
    }

    public init(key: string, method: string, data: any = null, respFormat: string = "", reqFormat: string = ""): void {
        this.key = key;
        this.method = method;
        this.respFormat = respFormat;
        this.reqFormat = reqFormat;
        if (reqFormat == "") {
            this.data = StringUtil.parseURLVariablesStr(data);
        } else {
            this.data = data;
        }
    }

    public clear() {
        this.key = "";
        this.method = "";
        this.respFormat = "";
        this.data = null;
    }

    public set key(value: string) {
        this._key = value;
    }
    public get key(): string {
        return this._key;
    }
}