import { _decorator, Component, UITransform, Slider } from "cc";
import { Events } from "../../Events";
const { ccclass, property, menu, disallowMultiple } = _decorator;

@ccclass("UIMaskSlider")
@menu("ui/basic_ui/UIMaskSlider.ts")
@disallowMultiple(true)

/**
 * 遮罩slider <br/>
 * @author ice
 */
export class UIMaskSlider extends Component {
    @property({ displayName: "progressMask", type: UITransform })
    progressMask: UITransform = null!;
    @property({ displayName: "progressBar", type: UITransform })
    progressBar: UITransform = null!;
    @property({ displayName: "slider", type: Slider })
    slider: Slider = null!;

    /** 进度条修改方法，进度条有修改会回调 
     * @progress 百分比
     * @target
    */
    public progressChangedFun: Function;

    start() {}

    // update(deltaTime: number) {
    // }

    public onEnable() {
        this.addToStage();
    }

    public onDisable() {
        this.removeFromStage();
    }

    private onSlide(target: Slider): void {
        this.progressMask.width = this.progressBar.width * target.progress;
        if(this.progressChangedFun)
        {
            this.progressChangedFun(target.progress,this);
        }
    }

    /** 设置progress */
    public setProgress(progress: number) {
        if (progress > 1) {
            progress = 1;
        }
        if (progress < 0) {
            progress = 0;
        }
        this.slider.progress = progress;
        this.progressMask.width = this.progressBar.width * progress;
    }

    /** 获取当前进度 */
    public get progress():number
    {
        return this.slider.progress;
    }
    
    protected addToStage() {
        this.slider!.node.on(Events.SliderEvent, this.onSlide, this);
    }

    protected removeFromStage() {
        this.slider!.node.off(Events.SliderEvent, this.onSlide, this);
    }
}
