    private static _svrTimeMS: number = -1;
    private static _lastSvrTimeMS = -1;
    public static get svrTimeMS(): number {
        let curTimeMs = TimeUtil.getCurMilliTime();
        if (Global._lastSvrTimeMS != -1 && Global._svrTimeMS != -1) {
            return curTimeMs - Global._lastSvrTimeMS + Global._svrTimeMS;
        } else {
            return curTimeMs;
        }
    }
    public static set svrTimeMS(timsMs: number) {
        Global._lastSvrTimeMS = TimeUtil.getCurMilliTime();
        Global._svrTimeMS = timsMs;
    }

