    /**
     * 获取平台对应的数字
     */
    public static get osid() {
        let platform = EOSID.Android;
        if (sys.isBrowser) {
            if (sys.isMobile) {
                platform = EOSID.H5;
            } else {
                platform = EOSID.PC;
            }
        } else if (sys.isNative) {
            if (sys.os == sys.OS.ANDROID) {
                platform = EOSID.Android;
            } else if (sys.os == sys.OS.IOS) {
                platform = EOSID.iOS;
            }
        } else if (sys.os == sys.OS.WINDOWS || sys.os == sys.OS.OSX || sys.os == sys.OS.LINUX) {
            platform = EOSID.PC;
        }
        return platform;
    }

    /**
     * 获取平台对应的名
     */
    public static get osname(): string {
        let platform = '';
        if (sys.isMobile) {
            platform = 'h5';
        } else {
            platform = 'pc';
        }
        return platform;
    }

    /**
     * 支持的压缩文件类型
     */
    public static get supportedRes(): ERES_TYPE {
        let str;
        if (sys.isNative && sys.os == sys.OS.IOS) {
            if (Global.deviceInfo && Global.deviceInfo.supportedEtc) {
                str = ERES_TYPE.ETC1;
            }
            return str;
        }
        str = ERES_TYPE.ETC1;
        return str;
    }

    public static backHomeUrl() {
        if (Global.closeBack)
            return;
        if (!Global.homeUrl || Global.homeUrl == '')
            return;

        if (window.top.location.href == Global.homeUrl) {
            let parent: any = window.parent;
            parent.CloseGameFrame();
            window.location.reload();
        }
        else
            window.top.location.replace(Global.homeUrl)
        // console.log("测试中")
    }

