import { loader } from "cc";

/**
 * HttpRequest 对象应使用 POST 方法还是 GET 方法。
 */
export enum HttpMethod {
	GET = "GET",
	POST = "POST",
}

/**
 * 指定如何接收已下载数据的值。
 */
export enum HttpResponseType {
	TEXT = "text",
	ARRAY_BUFFER = "arraybuffer",
	DOCUMENT = "document",
	JSON = "json",
}

/**
 * IHttpReq HTTP请求通用接口
 */
export default interface IHttpReq {
	/**
	 * 本次请求返回的数据，数据类型根据 responseType 设置的值确定。
	 */
	response: any;

	/**
	 * 设置返回的数据格式为文本（HttpResponseType.TEXT）还是二进制数据（HttpResponseType.ArrayBuffer）<br/>
	 * 注意：若尝试设置此属性为一个非法的值，运行时将使用HttpResponseType.TEXT。
	 * @default HttpResponseType.TEXT
	 */
	responseType: string;

	/**
	 * 表明在进行跨站(cross-site)的访问控制(Access-Control)请求时，是否使用认证信息(例如cookie或授权的header)。(这个标志不会影响同站的请求)
	 * @default false
	 */
	withCredentials: boolean;

	/**
	 * 请求超时的时间
	 * @type {number}
	 * @memberof IHttpReq
	 * @default 60s
	 */
	timeout: number;

	/**
	 * 请求进行中的状态
	 * @default false
	 */
	status: number;

	/**
	 * 初始化一个请求.<br/>
	 * 注意: 若在已经发出请求的对象上调用此方法，相当于立即调用abort().
	 * @param url 该请求所要访问的URL该请求所要访问的URL
	 * @param method 请求所使用的HTTP方法， 请使用 HttpMethod 定义的枚举值.
	 * @see HttpMethod
	 */
	open(url: string, listener: Function, failFunc?: Function, method?: HttpMethod): void;

	/**
	 * 发送请求.
	 * @param data 需要发送的数据
	 */
	send(data?: any): void;

	/**
	 * 如果请求已经被发送,则立刻中止请求.
	 */
	abort(): void;

	resend(): void;

	/**
	 * 返回所有响应头信息(响应头名和值), 如果响应头还没接受,则返回"".
	 */
	getAllResponseHeaders(): string;

	/**
	 * 给指定的HTTP请求头赋值.在这之前,您必须确认已经调用 open() 方法打开了一个url.
	 * @param header 将要被赋值的请求头名称.
	 * @param value 给指定的请求头赋的值.
	 */
	setRequestHeader(header: string, value: string): void;

	/**
	 * 返回指定的响应头的值, 如果响应头还没被接受,或该响应头不存在,则返回"".
	 * @param header 要返回的响应头名称
	 */
	getResponseHeader(header: string): string;
}

/**
 * http基础类
 */
export class HttpBase implements IHttpReq {
	private _xhr: XMLHttpRequest;
	private _responseType: HttpResponseType;
	private _listener: Function;
	private _withCredentials: boolean;
	private _url: string = "";
	private _method: HttpMethod;
	private _timeout: number = 5000;
	private headerObj: any;

	/**
	 * 初始化一个请求.注意，若在已经发出请求的对象上调用此方法，相当于立即调用abort().
	 * @param url 该请求所要访问的URL该请求所要访问的URL
	 * @param method 请求所使用的HTTP方法， 请使用 HttpMethod 定义的枚举值.
	 */
	public open(url: string, listener: Function, failFunc?: Function, method: HttpMethod = HttpMethod.GET): void {
		this._url = url;
		this._method = method;
		this._listener = listener || function () {};
		if (this._xhr) {
			this._xhr.abort();
			this._xhr = null;
		}
		this._xhr = this.getXHR();
		var self = this;
		this._xhr.timeout = this._timeout;
		this._xhr.onreadystatechange = function () {
			self._listener(this.response, self._xhr);
		};		
		this._xhr.ontimeout = () => {
            failFunc();
        }
        this._xhr.onerror = () => {
            failFunc();
        }

		this._xhr.open(this._method, this._url, true);
	}

	/**
	 * 发送请求.
	 * @param data 需要发送的数据
	 */
	public send(data?: any): void {
		if (this._responseType != null) {
			this._xhr.responseType = this._responseType;
		}
		if (this._withCredentials != null) {
			this._xhr.withCredentials = this._withCredentials;
		}
		if (this.headerObj) {
			for (let key in this.headerObj) {
				this._xhr.setRequestHeader(key, this.headerObj[key]);
			}
		}
		this._xhr.send(data);
	}

	/**
	 * 如果请求已经被发送,则立刻中止请求.
	 */
	public abort(): void {
		if (this._xhr) {
			this._xhr.abort();
		}
	}

	public resend(): void {
		if (!this._xhr) {
			return;
		}
		this._xhr.abort();
		this._xhr.open(this._method, this._url, true);
		this._xhr.send();
	}

	/**
	 * 返回所有响应头信息(响应头名和值), 如果响应头还没接受,则返回"".
	 */
	public getAllResponseHeaders(): string {
		if (!this._xhr) {
			return null;
		}
		let result = this._xhr.getAllResponseHeaders();
		return result ? result : "";
	}

	/**
	 * 给指定的HTTP请求头赋值.在这之前,您必须确认已经调用 open() 方法打开了一个url.
	 * @param header 将要被赋值的请求头名称.
	 * @param value 给指定的请求头赋的值.
	 */
	public setRequestHeader(header: string, value: string): void {
		if (!this.headerObj) {
			this.headerObj = {};
		}
		this.headerObj[header] = value;
	}

	/**
	 * 返回指定的响应头的值, 如果响应头还没被接受,或该响应头不存在,则返回"".
	 * @param header 要返回的响应头名称
	 */
	public getResponseHeader(header: string): string {
		if (!this._xhr) {
			return null;
		}
		let result = this._xhr.getResponseHeader(header);
		return result ? result : "";
	}

	private getXHR(): any {
		if (window) {
			if (window["XMLHttpRequest"]) {
				return new window["XMLHttpRequest"]();
			}
		} else {
			return new XMLHttpRequest();
		}
	}

	/**
	 * 表明在进行跨站(cross-site)的访问控制(Access-Control)请求时，是否使用认证信息(例如cookie或授权的header)。 默认为 false。(这个标志不会影响同站的请求)
	 */
	public get withCredentials(): boolean {
		return this._withCredentials;
	}

	public set withCredentials(value: boolean) {
		this._withCredentials = value;
	}

	public get response(): any {
		if (!this._xhr) {
			return null;
		}
		if (this._xhr.response != undefined) {
			return this._xhr.response;
		}

		if (this._responseType == "text") {
			return this._xhr.responseText;
		} else if (this._responseType == HttpResponseType.ARRAY_BUFFER) {
			let w: any = window;
			return w.convertResponseBodyToText(this._xhr["responseBody"]);
		} else if (this._responseType == HttpResponseType.DOCUMENT) {
			return this._xhr.responseXML;
		}
		return null;
	}

	public get responseType(): HttpResponseType {
		return this._responseType;
	}

	public set responseType(reptype: HttpResponseType) {
		this._responseType = reptype;
	}

	public set timeout(num: number) {
		this._timeout = num;
		if (this._xhr) {
			this._xhr.timeout = num;
		}
	}

	public get status(): number {
		if (!this._xhr) {
			return null;
		}
		return this._xhr.status;
	}
}
