import { SoundDefine } from "../../common/define/ResDefine";
import {
    assetManager,
    AssetManager,
    AudioClip,
    AudioSource,
    Component,
    _decorator,
    game,
    Game,
    Node,
} from "cc";
import { Macro } from "../../common/define/HotUpdateDefine";
import { Global } from "../../main/Global";
import { ResManager } from "./ResManager";
import { Resource } from "../hall/Resource";
import AudioEffectManager from "./AudioEffectManager";
import ComponentMgr from "../../mgr/ComponentMgr";

const { ccclass, property, menu } = _decorator;

@ccclass
@menu("runtime/AudioManager")
export default class AudioManager extends Component {
    private static _instance: AudioManager = null!;
    public static Instance() {
        // return this._instance || (this._instance = new AudioManager());
        return this._instance;
    }

    private isInited: boolean = false;
    /** 音乐 */
    public audioSourceNode: Node = null!;
    public audioSource: AudioSource = null!;
    /** 音乐地址 */
    private _audioSourceUrl: string = '';
    /** 音乐bundle包名 */
    private _audioSourceBundle: string = '';
    /** 音乐播放当前时间 */
    private _audioSourceCurentTime: number = 0;

    /** 音效管理器 */
    public audioEffManager: AudioEffectManager = null!;

    soundEnabled = true; //音效

    /** 背景音乐是否播放中 */
    musicHideEnabled = null;
    /** 音效是否播放中 */
    soundHideEnabled = null;

    /** 
     * 背景音乐
     * @deprecated 请调用Global的backgroundMusic接口，该接口准备去除
     */
    get musicEnabled(): boolean {
        return Global.backgroundMusic;
    }
    set musicEnabled(enable: boolean) {
        // Global.backgroundMusic = enable;
    }

    onLoad() {
        AudioManager._instance = this;
        this.init();
    }

    protected update(dt: number): void {

    }

    public init() {
        if (!this.isInited) {
            this.isInited = true;
            this.resetAudioSource();
            this.audioEffManager = this.node.addComponent(AudioEffectManager)

            //切后台把声音关闭
            game.on(Game.EVENT_HIDE, () => {
                if (!this.node || !this.node.isValid) {
                    return
                }
                this.musicHideEnabled = this.audioSource.playing;
                Log.d("切后台把声音关闭")
            });
            game.on(Game.EVENT_SHOW, () => {
                if (!this.node || !this.node.isValid) {
                    return
                }
                if (this.musicHideEnabled != null) {
                    if (this.musicEnabled)
                        this.musicOn()
                }
                Log.d("切前台把声音开启", this.musicHideEnabled, this.musicEnabled)
            });
        }
    }

    public musicOn() {
        if (!Global.backgroundMusic)
            return;
        if (this.musicHideEnabled != null && !this.musicHideEnabled)
            return;

        this.audioSource.play();
        this.audioSource.volume = 1;
        this.replayMusic()
    }

    public musicOff() {
        this.stopMusic();
        this.audioSource.volume = 0;
    }

    /**
     * 设置音效
     * @param enable 该参数准备去除，请不要调用
     */
    public setMusicEnabled(enable?: boolean) {
        enable = Global.backgroundMusic;
        if (enable) {
            this.musicHideEnabled = true;
            this.replayMusic();
        } else {
            this.stopMusic();
        }
    }

    public stopMusic() {
        this.audioSource.stop();
    }

    public setSoundEnabled(enable: boolean) {
    }

    public playEffect(
        url: string,
        bundleName: string = Macro.BUNDLE_RESOURCES,
        volume: number = 1,
        loop = false
    ) {
        if (!Global.firstClick)
            return;
        if (!Global.soundEffect)
            return;
        assetManager.loadBundle(
            bundleName,
            (error: Error, bundle: AssetManager.Bundle) => {
                if (!error) {
                    bundle.load(
                        url,
                        AudioClip,
                        null,
                        (error: any, clip: AudioClip) => {
                            if (!error) {
                                //this.audioSource.playOneShot(clip, volume);
                                let nameArr = url.split("/")
                                this.audioEffManager.play(nameArr[nameArr.length - 1], clip, volume, loop)
                            } else {
                                Log.w(error);
                            }
                        }
                    );
                } else {
                    Log.w(error);
                }
            }
        );
    }

    public playMusicBG() {
        if (!Global.backgroundMusic)
            return;
    }

    public playMusic(url: string, bundleName: string = Macro.BUNDLE_RESOURCES) {
        if (!url || url == '')
            return;
        this.resetAudioSource();
        ResManager.Instance().load(
            bundleName,
            url,
            AudioClip,
            () => { },
            (resCache: Resource.CacheData) => {
                this.audioSource.stop();
                let clip: any = resCache.data;
                this.audioSource.clip = clip;
                if (Global.backgroundMusic) {
                    this._audioSourceUrl = url;
                    this._audioSourceBundle = bundleName;
                    this.audioSource.play();
                }
            }
        );
    }

    private resetAudioSource() {
        if (this.audioSource) {
            this.audioSource.stop();
            this.audioSource.volume = 1;
            this.audioSource.clip = null;
            this.audioSource.loop = false;
            this.audioSource.destroy();
        }

        if (this.audioSourceNode) {
            this.audioSourceNode.removeFromParent();
            this.audioSourceNode.destroy();
        }

        this.audioSourceNode = new Node();
        this.node.addChild(this.audioSourceNode);
        this.audioSource = this.node.addComponent(AudioSource)!;
        this.audioSource.playOnAwake = false;
        this.audioSource.loop = true;
    }

    /**
     * 重播音乐
     * @returns 
     */
    public replayMusic() {
        if (!Global.backgroundMusic)
            return;
        if (this.musicHideEnabled != null && !this.musicHideEnabled)
            return;
        if (!this.audioSource)
            return;
        this._audioSourceCurentTime = this.audioSource.currentTime;
        this.audioSource.stop();
        this.audioSource.clip = null;
        this.playMusic(this._audioSourceUrl, this._audioSourceBundle);
        this.audioSource.currentTime = this._audioSourceCurentTime;
    }

    public stopEffect(url: string) {
        let nameArr = url.split("/")
        this.audioEffManager.stop(nameArr[nameArr.length - 1])
    }

    public stopAllEffect(exceptLoop = true) {
        this.audioEffManager.stopAll(exceptLoop);
    }

    public set pauseAllSound(yes: boolean) {
        if (yes) {
            this.audioEffManager.pauseAll();
        } else {
            this.audioEffManager.resumeAll();
        }

    }
}
export function playBtn() {
    AudioManager.Instance().playEffect(SoundDefine.sound_click);
}
