
import { _decorator, Component, Node, Label } from "cc";
import { GameUtils } from "../utils/GameUtil";
import TimeUtil from "../utils/TimeUtil";

const { ccclass, property, executeInEditMode } = _decorator;

@ccclass("RollValueCmp")
export class RollValueCmp extends Component {
    private lab_value: Label;  //lab组件
    private endValue: number = 0;
    private startValue: number = 0;
    private tempValue: number = 0;
    private isRolling: boolean = false;
    private startTime: number = 0;
    private rollDuration: number = 1000;
    private prefix = "";
    private callback: Function;
    private thisObj: any;

    /**label组件 */
    public onLoad() {
        this.lab_value = this.getComponent(Label);
    }

    /**设置数值，并停止滚动 */
    public setValue(value: number) {
        this.unschedule(this.rollValueTo);
        this.isRolling = false;
        this.endValue = value;
        let str = this.formatMoney(this.endValue);
        this.setLabel(str);
    }

    private formatMoney(value) {
        return this.prefix + GameUtils.formatMoney(value + "");
    }

    /**设置前缀 */
    public setPrefix(prefix: string) {
        this.prefix = prefix;
    }

    /**设置字符串内容 */
    public setLabel(labStr: string): void {
        this.lab_value.string = labStr;
    }

    /**停止滚动 */
    public stopRoll(): void {
        this.setValue(this.endValue);
    }

    /**数值增加(或减少)
     * @param isRoll 数值是否滚动增加(默认是)
     * @param rollDuration  滚动时间长度 (默认1秒钟)
     */
    public addValue(value: number, isRoll = true, rollDuration = 1000) {
        if (value == 0) {
            return;
        }

        if (isRoll) {
            if (this.isRolling) {
                this.endValue = this.endValue + value;
                this.startValue = this.tempValue;
                this.startTime = TimeUtil.getCurMilliTime();
                this.setRollDuration(rollDuration);
            } else {
                this.startValue = this.endValue;
                this.tempValue = this.endValue;
                this.endValue = this.endValue + value;
                this.startTime = TimeUtil.getCurMilliTime();
                this.setRollDuration(rollDuration);
                this.schedule(this.rollValueTo, 0.05);
                this.isRolling = true;
            }
        }
        else {
            let total = this.endValue + value;
            this.setValue(total);
        }
    }

    /**值增加至 */
    public addValueTo(value: number, isRoll = true, rollDuration = 2000, callback?: Function, thisObj?: any) {
        let add = value - this.endValue;
        this.addValue(add, isRoll, rollDuration);
        this.callback = callback;
        this.thisObj = thisObj;
    }

    /**设置滚动延时 */
    public setRollDuration(duration: number): void {
        if (isNaN(duration) || duration <= 0) {
            return;
        }
        this.rollDuration = duration;
    }

    private rollValueTo(): void {
        let curTime = TimeUtil.getCurMilliTime();
        let rate = (curTime - this.startTime) / this.rollDuration;
        this.tempValue = this.startValue + rate * (this.endValue - this.startValue);
        if (rate >= 1) {
            //停止定时器并设置值
            this.setValue(this.endValue);
            if (this.callback) {
                this.callback.call(this.thisObj)
            }
            return;
        }
        let str = this.prefix + this.formatMoney(this.tempValue);
        this.setLabel(str);
    }
}