    public handlerPlatformMessage(message: any) {
        let mesObj = message;
        mesObj = JSON.parse(decodeURIComponent(message));
        let type = mesObj.class;
        let func = mesObj.function;
        let args = mesObj.args;
        LogUtil.debug(
            "handlerWebJsToNativeMessage,type:" + type + "func->" + func
        );
        Log.d(`====handlerPlatformMessage======${JSON.stringify(mesObj)}`);
        if (type == "Webview" && func == "hide") {
            let webKey = "ThirdPartyWV";
            let csKey = "CHAT";
            if (args && (args.id == webKey || args.id == csKey)) {
                Global.gameCtrl.gameBack(false);
                setTimeout(() => {
                    NativeApi.closeWebView();
                    NativeApi.lockOrientation(false);
                    AudioManager.Instance().playMusicBG();
                }, 200);
            } else {
                Global.gameCtrl.gameBack();
                //解决从游戏退出时会出现黑屏
                setTimeout(() => {
                    NativeApi.closeWebView();
                }, 100);
            }
        } else if (type == "Webview" && func == "eventListener") {
            //webview 事件
            let event = args.event;
            LogUtil.log("webview event," + event);
            // if (event == "show") {
            // } else if (event == "loaded") {
            // } else if (event == "close") {
            // }
            CustomEventMgr.fire(EventType.WEBVIEW_STATE, event);
        } else if (type == "Download" && func == "eventListener") {
            CustomEventMgr.fire(EventType.GMAE_DOWNLOAD, args);
        } else if (type == "Zip" && func == "decompress") {
            CustomEventMgr.fire(EventType.GMAE_DECOMPRSS, args);
        } else if (type == "Device" && func == "info") {
            CustomEventMgr.fire(EventType.NATIVE_GET_INFO, args);
            if (args && args.info) Global.deviceInfo = JSON.parse(args.info);
            Log.d(`===Global.deviceInfo 1=====${Global.deviceInfo}`);
        } else if (type == "Storage" && func == "setItem") {
            LogUtil.debug(
                "handlerPlatformMessage args:" + JSON.stringify(args)
            );
            let key = args.key;
            let value = args.value;
            if (key == "musicSwitch") {
                let musicSwitch = value == "true" ? true : false;
                Global.gameCtrl.gameBackAndSaveMusicSwitch(musicSwitch);
            }
        }
        // else if (type == "onOpenView") {
        //     LogUtil.debug("onOpenView");
        // }
    }

