    openURL(url: string) {
        if (sys.os == sys.OS.IOS) {
            native.reflection.callStaticMethod("JsbInterface", "openURL:", url);
        } else if (sys.os == sys.OS.ANDROID) {
            native.reflection.callStaticMethod(
                "com/cocos/game/JsbInterface",
                "openURL",
                "(Ljava/lang/String;)V",
                url
            );
        }
    }

