    /**
     * 创建游戏下载任务
     * @param id
     * @param url
     * @param fileName
     * @param timeout
     * @param priority
     * @param retry
     * @param retryInterval
     */
    public static createDownload(
        id: string,
        url: string,
        fileName: string,
        timeout?: number,
        priority?: number,
        retry?: number,
        retryInterval?: number
    ) {
        LogUtil.debug("createDownload");
        timeout = 120;
        priority = 0;
        retry = 3;
        retryInterval = 30;
        // Global.gameCtrl.mainUITs.node.active = true;
        if (sys.os == sys.OS.IOS) {
            native.reflection.callStaticMethod(
                "JsbInterface",
                "createDownload:url:fileName:timeout:priority:retry:retryInterval:",
                id,
                url,
                fileName,
                timeout,
                priority,
                retry,
                retryInterval
            );
        } else if (sys.os == sys.OS.ANDROID) {
            native.reflection.callStaticMethod(
                "com/cocos/game/JsbInterface",
                "createDownload",
                "(Ljava/lang/String;Ljava/lang/String;Ljava/lang/String;IIII)V",
                id,
                url,
                fileName,
                timeout,
                priority,
                retry,
                retryInterval
            );
        }
    }
