    /**
     * 写入文件
     * @param data
     * @param file
     * @returns
     */
    public static writeStringToFile(data: any, file: string) {
        if (!sys.isNative) return;
        let storePath = NativeApi.getStorePath();
        if (!native.fileUtils.isDirectoryExist(storePath)) {
            // 目录不存在，创建
            native.fileUtils.createDirectory(storePath);
        }
        let flag = native.fileUtils.writeStringToFile(data, storePath + file);
        Log.d(`==writeStringToFile1==${storePath + file},  ${flag}===`);
    }

    /**
     * 获取文件
     * @param file
     * @returns
     */
    public static getStringFromFile(file: string) {
        if (!sys.isNative) return;
        let storePath = NativeApi.getStorePath();
        let fileName = storePath + file;
        let exist = native.fileUtils.isFileExist(fileName);
        Log.d(`====getStringFromFile====${fileName}, ${exist}`);
        if (exist) {
            return native.fileUtils.getStringFromFile(fileName);
        } else {
            Log.w(`getWriteFile not find file: ${file}`);
        }
    }

    /**
     * 删除文件
     * @param file
     * @returns
     */
    public static removeFile(file: string) {
        if (!sys.isNative) return;
        let storePath = NativeApi.getStorePath();
        let fileName = storePath + file;
        let exist = native.fileUtils.isFileExist(fileName);
        Log.d(`====removeFile====${fileName}, ${exist}`);
        if (exist) {
            return native.fileUtils.removeFile(fileName);
        } else {
            Log.w(`removeFile not find file: ${file}`);
        }
    }

    static getStorePath() {
        let platformId = Global.platformId ? Global.platformId + "/" : "";
        return (
            (native.fileUtils ? native.fileUtils.getWritablePath() : "/") +
            platformId
        );
    }
