import { sys } from "cc";
import NativeApi from "./NativeApi";
import PlatformApi from "./PlatformApi";
import WebApi from "./WebApi";


class SdkManager {
    public static api: PlatformApi;
    public static getIns() {
        if (!this.api) {
            if (sys.isNative) {
                this.api = new NativeApi();
            }
            else {
                this.api = new WebApi();
            }
   
        }
        return this.api;
    }
    
}

export default SdkManager.getIns();
