import { game, instantiate, Prefab, ResolutionPolicy, sys, view, _decorator, Layers } from "cc";
import { UIID } from "./../framework/ui/UIDefined";
import { Tips } from "../common/components/Tips";
import { Macro } from "../common/define/HotUpdateDefine";
import SdkManager from "../common/sdk/SdkManager";
import LogUtil from "../common/utils/LogUtil";
import { UIManager } from "../framework/ui/UIManager";
import { Global } from "../main/Global";
import { ResManager } from "../framework/manager/ResManager";
import NativeApi from "../common/sdk/NativeApi";
import { ResDefine } from "../common/define/ResDefine";
import { ScreenType } from "../framework/ui/UIView";
import i18n from "../framework/language/i18n";

const { ccclass, menu } = _decorator;

@ccclass("ComponentMgr")
@menu("runtime/ComponentMgr")
export default class ComponentMgr {
    private static _instance: ComponentMgr = null!;
    public static getInstance() {
        return this._instance || (this._instance = new ComponentMgr());
    }

    init() {
        if (sys.isNative == false) {
            window.addEventListener(
                "message",
                function (e) {
                    var data = JSON.parse(e.data || "{}");
                    LogUtil.debug("web meg back,data:" + JSON.stringify(data));
                    if (data.method == "back" || data.method == "thback") {
                        if (data.method == "thback") {
                            NativeApi.lockOrientation(false);
                        }
                        LogUtil.debug("back");
                        let musicSwitch = data.musicSwitch;

                        let yuFrame: any = document.getElementById("YuFrame1");
                        yuFrame.src = "about:blank";
                        try {
                            yuFrame.document.write("");
                            yuFrame.document.clear();
                        } catch (e) { }

                        // Global.gameCtrl.mainUITs.node.active = true;
                        // Global.gameCtrl.mainUITs.gameBack();
                        Global.gameCtrl.gameBack();
                        Global.gameCtrl.gameBackAndSaveMusicSwitch(musicSwitch);

                        //把iframe从页面移除
                        document.getElementById("YuFrame1").remove();
                        document.getElementById("hello").remove();
                    }
                },
                false
            );
        }
    }
    /**
     * 根据字符串飘字提示
     * @param str
     */
    public static showTips(str: String) {
        ResManager.Instance().load(
            Macro.BUNDLE_RESOURCES,
            ResDefine.UI_TIPS_PREFAB,
            Prefab,
            () => { },
            (res) => {
                let data = res.data;
                let tips: any = instantiate(data)!;
                // tips.parent = UIManager.getInstance().getUI(
                //     UIID.UIAniLayer
                // ).node;
                tips.angle = Global.gameScreenType == ScreenType.Landscape ? 0 : 90;
                tips.parent = UIManager.getInstance().getTopUI().node;
                tips.getComponent(Tips).initTips(str);
            }
        );
    }
    /**
     * 根据字符串id飘字提示
     * @param id 字符串id,适配多国语言
     */
    public static showTipsById(id: number) {
        let str = i18n.tr(id);
        ResManager.Instance().load(
            Macro.BUNDLE_RESOURCES,
            ResDefine.UI_TIPS_PREFAB,
            Prefab,
            () => { },
            (res) => {
                let data = res.data;
                let tips: any = instantiate(data)!;
                // tips.parent = Global.gameCtrl.topLayer;
                tips.parent = UIManager.getInstance().getTopUI().node;
                // tips.parent = UIManager.getInstance().getUI(
                //     UIID.UIAniLayer
                // ).node;
                tips.angle = Global.gameScreenType == ScreenType.Landscape ? 0 : 90;
                tips.getComponent(Tips).initTips(str);
            }
        );
    }

    /**
     * 打开网页iframe
     * @param url
     */
    public static showWebIframe(url: string) {
        console.log("showWebIframe,url:" + url);
        var parentdiv = document.createElement("div");
        // parentdiv.style.width = "100%";
        // parentdiv.style.height = "100%";
        parentdiv.style.display = "block";
        parentdiv.style.position = "absolute";
        parentdiv.style.bottom = "0px";
        parentdiv.style.left = "0px";
        parentdiv.id = "hello";
        // document.getElementById("GameDiv").appendChild(parentdiv);
        document.body.appendChild(parentdiv);
        var myIframe = document.createElement("iframe");
        myIframe.width = "100%";
        myIframe.height = "100%";
        myIframe.id = "YuFrame1";
        myIframe.name = "YuFrame1";
        myIframe.frameBorder = "no";
        myIframe.marginWidth = "0px";
        myIframe.marginWidth = "0px";
        myIframe.scrolling = "no";
        // myIframe.style.position = "absolute";
        let style: any = myIframe.style;
        // style.position = "relative";
        style.position = "fixed";
        style.borderfra = "no";
        style.left = "0px";
        style.top = "0px";
        // style.marginheight = "0px";
        // style.marginwidth = "0px";
        // style.allowTransparency = "true";
        // style.scrolling = "no";
        // style.borderWidth = "0px";
        parentdiv.appendChild(myIframe);

        let yuFrame: any = document.getElementById("YuFrame1");
        // yuFrame.left = "0px";
        // yuFrame.top = "0px";
        yuFrame.src = url;
    }
    public static copyStringToClipboard(str: string) {
        let isOk = SdkManager.setClipboard(str);
        if (isOk == true) {
            ComponentMgr.showTipsById(107054);
        }
    }

    public static openCustomKeyboard(defaultText: string = "", isPassword: boolean = false, isPlain: boolean = true) {
        UIManager.getInstance().open(UIID.UISoftKeyboard, { label: defaultText, psword: isPassword, plain: isPlain });
    }
}
