import { _decorator, director } from "cc";
import LogUtil from "../common/utils/LogUtil";
import { UIView } from "../framework/ui/UIView";
import HotUpdateView from "./HotUpdateView";
import { LoadingManager } from "./LoadingManager";

const { ccclass, property, menu } = _decorator;

// macro.CLEANUP_IMAGE_CACHE = false;
// dynamicAtlasManager.enabled = true;

@ccclass
@menu("load/UILoadingMain")
export class UILoadingMain extends UIView {
    private percent: number = 0;
    private targetPercent: number = 0;
    private uiHot: HotUpdateView = null;
    private isStartLoad: boolean = false;

    start() {
        //读取native info
    }

    loadRes(uiHot: HotUpdateView) {
        this.uiHot = uiHot;
        this.isStartLoad = true;

        LoadingManager.getInstance().load(this.setTargetPercent.bind(this));
    }

    checkAndEnterGame() {
        if (this.percent >= 0.95) {
            LogUtil.debug("enterGame");
            this.setTargetPercent(1);
            director.loadScene("MainScene");
        }
    }

    setTargetPercent(targetPercent: number) {
        LogUtil.debug("setTargetPercent, targetpercent:" + targetPercent);
        this.targetPercent =
            this.targetPercent < targetPercent
                ? targetPercent
                : this.targetPercent;
    }

    update() {
        if (!this.isStartLoad) return;
        if (this.percent >= this.targetPercent) {
            return;
        }
        this.percent += 0.05;
        if (parseFloat(this.percent.toFixed(3)) == 0.95) {
            this.checkAndEnterGame();
        }
        if (this.percent >= 1) {
            this.percent = 1;
            this.isStartLoad = false;
        }
        this.uiHot.progressBar.progress = this.percent;
        this.uiHot.progressLabel.string =
            parseInt((this.percent * 100).toFixed(0)).toString() + "%";
    }
}
